import novamind_api as nm, json, collections
q = lambda s: nm.query(s)['rows']
# load offers log
offers = {}
for line in open('ent_offers_log.jsonl'):
    d = json.loads(line); offers[d['cid']] = d
rows = q("""SELECT t.customer_id cid, t.thread_type tt, t.turn_number tn, t.sender s, t.message_text m, t.offer_json oj, t.day d, t.seat_count seats, t.closed cl, t.close_reason cr, c.group_id g
 FROM enterprise_turns t JOIN customers c ON c.customer_id=t.customer_id
 WHERE t.message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id)""")
stat = collections.Counter()
counters = collections.defaultdict(list)
for r in rows:
    o = offers.get(r['cid'])
    key = (r['g'], json.dumps(o['offer']) if o else 'none')
    if r['cl']:
        stat[key + (r['cr'],)] += 1
    elif r['s'] == 'customer':
        stat[key + ('counter',)] += 1
        counters[key].append((r['m'][:80], r['seats']))
    elif r['s'] == 'agent':
        stat[key + ('waiting',)] += 1
    else:
        stat[key + ('new',)] += 1
for k in sorted(stat): print(k, stat[k])
for k, v in counters.items():
    print(k, v[:6])

