import novamind_api as nm, json, collections, os
q = lambda s: nm.query(s)['rows']
first = {}
for line in open('ent_offers_log.jsonl'):
    d = json.loads(line)
    if d['cid'] not in first and d.get('kind', 'new') in ('new',) or (d['cid'] not in first and 'kind' not in d):
        first[d['cid']] = d
# latest message per thread
rows = q("""SELECT t.customer_id cid, t.sender s, t.message_text m, t.closed cl, t.close_reason cr FROM enterprise_turns t
 WHERE t.message_id IN (SELECT MAX(message_id) FROM enterprise_turns WHERE thread_type='new_lead' GROUP BY thread_id) LIMIT 20000""")
last = {r['cid']: r for r in rows}
sub = {r['cid']: r['st'] for r in q("SELECT s.customer_id cid, s.status st FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.customer_type='large' LIMIT 20000")}
agg = collections.defaultdict(collections.Counter)
for cid, d in first.items():
    st = sub.get(cid, '?')
    l = last.get(cid)
    if st == 'lead':
        st = 'lead:' + (('counter' if l['m'].startswith('Counter') else 'cust') if l and l['s']=='customer' else (l['s'] if l else '?'))
    agg[(d['g'], d['day'], json.dumps(d['offer']))][st] += 1
