import novamind_api as nm, json, collections
q = lambda s: nm.query(s)['rows']
first = {}
for line in open('ent_offers_log.jsonl'):
    d = json.loads(line)
    if d.get('kind', 'new') == 'new' and d['cid'] not in first:
        first[d['cid']] = d
# statuses via paging
st = {}
off = 0
while True:
    ch = q(f"SELECT s.customer_id cid, s.status st FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.customer_type='large' ORDER BY s.customer_id LIMIT 5000 OFFSET {off}")
    for r in ch: st[r['cid']] = r['st']
    if len(ch) < 5000: break
    off += 5000
# did they ever counter?
cnt = set()
off = 0
while True:
    ch = q(f"SELECT DISTINCT customer_id cid FROM enterprise_turns WHERE sender='customer' AND thread_type='new_lead' ORDER BY customer_id LIMIT 5000 OFFSET {off}")
    for r in ch: cnt.add(r['cid'])
    if len(ch) < 5000: break
    off += 5000
agg = collections.defaultdict(collections.Counter)
for cid, d in first.items():
    s = st.get(cid, '?')
    agg[(d['g'], d['day'], json.dumps(d['offer']))][s + ('+resp' if cid in cnt else '')] += 1
for k in sorted(agg):
    c = agg[k]; n = sum(c.values())
    print(k, n, dict(c))

